customDetailFormulas.calculatedFormula:
IF(
AND(

/* Time Spent >= 15 Minutes */

(
IF(
CONTAINS(Event__c.Time_Spent_Auto__c,"h"),
VALUE(
TRIM(
LEFT(
Event__c.Time_Spent_Auto__c,
FIND("h",Event__c.Time_Spent_Auto__c)-1
)
)
)*60,
0
)
+
IF(
CONTAINS(Event__c.Time_Spent_Auto__c,"m"),
VALUE(
TRIM(
MID(
Event__c.Time_Spent_Auto__c,
FIND("h",Event__c.Time_Spent_Auto__c)+1,
FIND("m",Event__c.Time_Spent_Auto__c)-FIND("h",Event__c.Time_Spent_Auto__c)-1
)
)
),
0
)
)>=15,

/* Location within 1 KM */

AND(
ABS(
VALUE(
LEFT(
Event__c.CheckIn_Location__c,
FIND(",",Event__c.CheckIn_Location__c)-1
)
)
-
VALUE(
LEFT(
Event__c.CheckOut_Location__c,
FIND(",",Event__c.CheckOut_Location__c)-1
)
)
)<=0.009,

ABS(
VALUE(
MID(
Event__c.CheckIn_Location__c,
FIND(",",Event__c.CheckIn_Location__c)+1,
20
)
)
-
VALUE(
MID(
Event__c.CheckOut_Location__c,
FIND(",",Event__c.CheckOut_Location__c)+1,
20
)
)
)<=0.012
),

/* Check-in During Office Hours */

AND(
HOUR(TIMEVALUE(Event__c.CheckIn_Date__c + (5.5/24)))>=8,
HOUR(TIMEVALUE(Event__c.CheckIn_Date__c + (5.5/24)))<20
),

/* Recap Character Count */

Event__c.Recap_Character_Count__c >= 150

),

"Yes",
"No"
)
